'sa-raison':d=>{ const u0=rnd(-20,100), r=d===1?rnd(2,15):rnd0(-15,15); const ar=Math.random()<(d===3?0.4:0); const v=[u0]; for(let i=1;i<4;i++) v.push(ar?v[i-1]+r+i:v[i-1]+r);
  if(d<3) return item('sa-raison',[`Voici les premiers termes d’une suite arithmétique : ${v.map(fmtN).join(' ; ')}.`],qN('**Donne** sa raison.',r,{aide:['Je calcule la différence entre deux termes qui se suivent.'],corr:[`${fmtN(v[1])} − ${par(v[0])} = ${fmtN(r)}`],rep:`La raison est ${fmtN(r)}.`}));
  const dif=v.slice(1).map((x,i)=>x-v[i]); const ok=new Set(dif).size===1; return item('sa-raison',[`Voici les premiers termes d’une suite : ${v.map(fmtN).join(' ; ')}.`],qV('Cette suite est arithmétique.',ok,{aide:['Je calcule toutes les différences entre deux termes qui se suivent.'],corr:[`Différences : ${dif.map(fmtN).join(' ; ')}`,ok?'Toutes égales : arithmétique.':'Pas toutes égales : pas arithmétique.'],rep:ok?'La suite est arithmétique.':'La suite n’est pas arithmétique.'})); },
'sa-formule':d=>{ const u0=rnd(-20,200), r=rnd0(-15,25), n=rnd(8,60); const from1=d===3;
  if(d===1) return item('sa-formule',[`(uₙ) est une suite arithmétique de premier terme u₀ = ${fmtN(u0)} et de raison r = ${fmtN(r)}.`],qE('**Exprime** uₙ en fonction de n.',`${u0}+${r}n`.replace('+-','-'),'any',{v:'n',aide:['uₙ = u₀ + n × r.'],corr:[`uₙ = ${fmtN(u0)} ${r<0?'−':'+'} ${Math.abs(r)}n`],rep:`uₙ = ${fmtN(u0)} ${r<0?'−':'+'} ${Math.abs(r)}n.`}));
  const val=from1?u0+(n-1)*r:u0+n*r; return item('sa-formule',[`(uₙ) est une suite arithmétique avec ${from1?'u₁':'u₀'} = ${fmtN(u0)} et r = ${fmtN(r)}.`],qN(`**Calcule** u${SUBN(n)}.`,val,{aide:[from1?'uₙ = u₁ + (n − 1) × r.':'uₙ = u₀ + n × r.'],corr:[from1?`u${SUBN(n)} = ${fmtN(u0)} + ${n-1} × ${par(r)} = ${fmtN(val)}`:`u${SUBN(n)} = ${fmtN(u0)} + ${n} × ${par(r)} = ${fmtN(val)}`],rep:`u${SUBN(n)} = ${fmtN(val)}.`})); },
'sa-rang':d=>{ const u0=rnd(50,400), r=rnd(5,60), S=u0+r*rnd(5,30)+rnd(1,r-1); const n=Math.ceil((S-u0)/r);
  return item('sa-rang',[`uₙ = ${u0} + ${r}n.`],qN(`**Détermine** le plus petit entier n tel que uₙ ≥ ${fmtN(S)}.`,n,{aide:[`Je résous ${u0} + ${r}n ≥ ${fmtN(S)}.`,'n est un entier : je prends le premier entier qui convient.'],corr:[`${r}n ≥ ${fmtN(S-u0)}`,`n ≥ ${fmtN(S-u0)} ÷ ${r} ≈ ${fx(roundTo((S-u0)/r,2))}`,`n = ${n} (u${SUBN(n)} = ${fmtN(u0+r*n)})`],rep:`Le plus petit entier est n = ${n}.`})); }
