  if(d<3) return item('d2-coef',[`f(x) = ${quadStr(a,b,c)}.`],qN(`**Donne** le coefficient ${k}.`,v,{aide:['f(x) = ax² + bx + c : a devant x², b devant x, c seul.','Je garde le signe.'],corr:[`a = ${fmtN(a)} ; b = ${fmtN(b)} ; c = ${fmtN(c)}`],rep:`${k} = ${fmtN(v)}.`}));
