'd2-sommet':d=>{ const a=pick(d===1?[1,-1]:[1,-1,2,-2,0.5,-0.5,3]), al=rnd(-5,6), be=rnd(-9,12); const b=-2*a*al, c=a*al*al+be;
  if(d<3) return item('d2-sommet',[`f(x) = ${quadStr(a,b,c)}.`],qN('**Calcule** l’abscisse α du sommet de la parabole.',al,{aide:['α = −b ÷ (2a).'],corr:[`α = −${par(b)} ÷ (2 × ${par(a)}) = ${fmtN(-b)} ÷ ${fmtN(2*a)} = ${fmtN(al)}`],rep:`L’abscisse du sommet est α = ${fmtN(al)}.`}));
  return item('d2-sommet',[`f(x) = ${quadStr(a,b,c)}.`],qN(`**Calcule** le ${a<0?'maximum':'minimum'} de f.`,be,{aide:['α = −b ÷ (2a).',`Le ${a<0?'maximum':'minimum'} est f(α).`],corr:[`α = ${fmtN(-b)} ÷ ${fmtN(2*a)} = ${fmtN(al)}`,`f(${fmtN(al)}) = ${fmtN(be)}`],rep:`Le ${a<0?'maximum':'minimum'} de f est ${fmtN(be)}, atteint en x = ${fmtN(al)}.`})); },
'd2-delta':d=>{ let a,b,c; if(d===1){ a=rnd0(-3,3); b=rnd(-8,8); c=rnd(-8,8); } else { const kind=pick(['+','0','-']); a=rnd0(-3,3); if(kind==='0'){ const r=rnd(-4,4); b=-2*a*r; c=a*r*r; } else { b=rnd(-8,8); c=rnd(-8,8); } }
  const D=b*b-4*a*c; if(d===1) return item('d2-delta',[`On veut résoudre ${quadStr(a,b,c)} = 0.`],qN('**Calcule** le discriminant Δ.',D,{aide:['Δ = b² − 4ac.',`a = ${fmtN(a)} ; b = ${fmtN(b)} ; c = ${fmtN(c)}.`],corr:[`Δ = ${par(b)}² − 4 × ${par(a)} × ${par(c)} = ${b*b} ${-4*a*c<0?'−':'+'} ${Math.abs(4*a*c)} = ${fmtN(D)}`],rep:`Δ = ${fmtN(D)}.`}));
  const n=D>0?2:D===0?1:0; return item('d2-delta',[`On veut résoudre ${quadStr(a,b,c)} = 0.`],qN('Combien cette équation a-t-elle de solutions ?',n,{aide:['Je calcule Δ = b² − 4ac, puis je regarde son signe.'],corr:[`Δ = ${fmtN(D)} ${D>0?'> 0':D<0?'< 0':'= 0'}`,`${n} solution${n>1?'s':''}`],rep:`L’équation a ${n} solution${n>1?'s':''}.`})); },
