  if(d<3) return item('de-extr',[`f(x) = ${quadStr(a,b,c)}.`],qN('**Résous** f′(x) = 0.',al,{aide:['f′(x) = 2ax + b.','Je résous 2ax + b = 0.'],corr:[`f′(x) = ${lin(2*a,b)}`,`${lin(2*a,b)} = 0 ⟹ x = ${fmtN(al)}`],rep:`f′(x) = 0 pour x = ${fmtN(al)}.`}));
