/* ===== Degré 3 (Tle) ===== */
Object.assign(GENS,{
'd3-cube':d=>{ if(d===1){ const x=pick([-4,-3,-2,-1,2,3,4,5,10,0.5,-0.5,1.5]); return item('d3-cube',['f(x) = x³.'],qN(`**Calcule** f(${fmtN(x)}).`,x**3,{aide:[`${par(x)}³ = ${par(x)} × ${par(x)} × ${par(x)}.`],corr:[`${par(x)}³ = ${fmtN(roundTo(x**3,4))}`],rep:`f(${fmtN(x)}) = ${fmtN(roundTo(x**3,4))}.`})); }
  const a=rnd0(-3,3), b=rnd(-6,6), c=rnd(-9,9), e=rnd(-9,9), x=d===2?rnd(-2,3):rnd(-3,3); const v=a*x**3+b*x*x+c*x+e;
  return item('d3-cube',[`f(x) = ${polyStr([e,c,b,a])}.`],qN(`**Calcule** f(${fmtN(x)}).`,v,{aide:[`Je remplace x par ${par(x)}.`,`${par(x)}³ = ${fmtN(x**3)} ; ${par(x)}² = ${fmtN(x*x)}.`],corr:[`f(${fmtN(x)}) = ${fmtN(a*x**3)} ${b*x*x<0?'−':'+'} ${fmtN(Math.abs(b*x*x))} ${c*x<0?'−':'+'} ${fmtN(Math.abs(c*x))} ${e<0?'−':'+'} ${Math.abs(e)} = ${fmtN(v)}`],rep:`f(${fmtN(x)}) = ${fmtN(v)}.`})); },
'd3-extr':d=>{ let x1,x2; do{ x1=rnd(-4,3); x2=rnd(-3,5); }while(x1>=x2); const k=pick([1,-1]); /* f′(x) = 3k(x − x1)(x − x2) */ const a=k, b=-1.5*k*(x1+x2), c=3*k*x1*x2; if(!Number.isInteger(b)) return null; const e=rnd(-5,5);
  const f=x=>a*x**3+b*x*x+c*x+e; const fp=polyStr([c,2*b,3*a]);
  if(d<3) return item('d3-extr',[`f(x) = ${polyStr([e,c,b,a])}.`,`f′(x) = ${fp}.`],qN('**Calcule** la plus petite solution de f′(x) = 0.',x1,{aide:['Je calcule le discriminant de f′(x).','x = (−B ± √Δ) ÷ (2A), avec f′(x) = Ax² + Bx + C.'],corr:[`Δ = ${fmtN((2*b)**2-4*3*a*c)}`,`Solutions : ${fmtN(x1)} et ${fmtN(x2)}`],rep:`La plus petite solution est ${fmtN(x1)}.`}));
  const isMax=k>0; return item('d3-extr',[`f(x) = ${polyStr([e,c,b,a])}.`,`f′(x) = ${fp} s’annule en ${fmtN(x1)} et en ${fmtN(x2)}.`],qN(`**Calcule** le ${isMax?'maximum':'minimum'} local de f, atteint en x = ${fmtN(x1)}.`,f(x1),{aide:[`Je calcule f(${fmtN(x1)}).`],corr:[`Le coefficient de x² dans f′ est ${3*a} : f′ est ${isMax?'positive puis négative':'négative puis positive'} autour de ${fmtN(x1)}.`,`f(${fmtN(x1)}) = ${fmtN(f(x1))}`],rep:`Le ${isMax?'maximum':'minimum'} local est ${fmtN(f(x1))}.`})); }
});
