  if(d===1) return item('p2-indep',[`A et B sont indépendants. P(A) = ${fx(pa)} et P(B) = ${fx(pb)}.`],qN('**Calcule** P(A ∩ B).',roundTo(pa*pb,4),{aide:['Indépendants : P(A ∩ B) = P(A) × P(B).'],corr:[`${fx(pa)} × ${fx(pb)} = ${fx(roundTo(pa*pb,4))}`],rep:`P(A ∩ B) = ${fx(roundTo(pa*pb,4))}.`}));
