/* ===== Vecteurs de l’espace (Tle) ===== */
const P3s=(n,p)=>`${n}(${p.map(fmtN).join(' ; ')})`;
Object.assign(GENS,{
'v3-coord':d=>{ const A=[rnd(-5,5),rnd(-5,5),rnd(0,8)], B=[rnd(-5,8),rnd(-5,8),rnd(0,12)]; const k=pick([0,1,2]); const nm=['première','deuxième','troisième'][k]; const v=B[k]-A[k];
  return item('v3-coord',[`${P3s('A',A)} et ${P3s('B',B)}.`],qN(`**Calcule** la ${nm} coordonnée du vecteur ~AB~.`,v,{aide:['Arrivée moins départ.'],corr:[`${fmtN(B[k])} − ${par(A[k])} = ${fmtN(v)}`,`~AB~(${B.map((b,i)=>fmtN(b-A[i])).join(' ; ')})`],rep:`La ${nm} coordonnée de ~AB~ est ${fmtN(v)}.`})); },
'v3-dist':d=>{ const T=[[2,3,6,7],[1,4,8,9],[2,6,9,11],[6,8,24,26],[4,4,7,9],[2,10,11,15],[12,9,20,25],[3,4,12,13]]; if(d===1){ const t=pick(T); const s=shuffle([t[0],t[1],t[2]]).map(x=>x*pick([1,-1])); return item('v3-dist',[`~u~(${s.map(fmtN).join(' ; ')}).`],qN('**Calcule** la norme de ~u~.',t[3],{aide:['‖~u~‖ = √(x² + y² + z²).'],corr:[`${s.map(x=>par(x)+'²').join(' + ')} = ${t[3]**2}`,`√${t[3]**2} = ${t[3]}`],rep:`La norme de ~u~ est ${t[3]}.`})); }
  const A=[rnd(-4,4),rnd(-4,4),rnd(0,5)], B=[rnd(-4,6),rnd(-4,6),rnd(0,9)]; const D=Math.hypot(B[0]-A[0],B[1]-A[1],B[2]-A[2]); if(D===0) return null;
  return item('v3-dist',[`${P3s('A',A)} et ${P3s('B',B)}.`],qN('**Calcule** la distance AB. **Arrondis** au centième.',D,{arr:2,aide:['Je calcule les différences de coordonnées.','AB = √(différence x² + différence y² + différence z²).'],corr:[`~AB~(${B.map((b,i)=>fmtN(b-A[i])).join(' ; ')})`,`AB = √${roundTo(D*D,6)} ≈ ${fx(roundTo(D,2))}`],rep:`AB ≈ ${fx(roundTo(D,2))}.`})); },
'v3-milieu':d=>{ const A=[rnd(-6,6),rnd(-6,6),rnd(0,10)], B=[rnd(-6,6),rnd(-6,6),rnd(0,10)]; const I=A.map((a,i)=>(a+B[i])/2); const k=pick([0,1,2]);
  return item('v3-milieu',[`${P3s('A',A)} et ${P3s('B',B)}.`],qN(`**Calcule** la ${['première','deuxième','troisième'][k]} coordonnée du milieu I de [AB].`,I[k],{aide:['Je fais la moyenne des deux coordonnées.'],corr:[`(${fmtN(A[k])} + ${par(B[k])}) ÷ 2 = ${fmtN(I[k])}`],rep:`I(${I.map(fmtN).join(' ; ')}).`})); },
'v3-somme':d=>{ const u=[rnd(-6,6),rnd(-6,6),rnd(-6,6)], v=[rnd(-6,6),rnd(-6,6),rnd(-6,6)]; const w=u.map((x,i)=>x+v[i]);
  if(d<3){ const g=`(${w.map(fmtN).join(' ; ')})`; return item('v3-somme',[`~u~(${u.map(fmtN).join(' ; ')}) et ~v~(${v.map(fmtN).join(' ; ')}).`],qC('Quelles sont les coordonnées de ~u~ + ~v~ ?',[g,`(${u.map((x,i)=>fmtN(x-v[i])).join(' ; ')})`,`(${w.slice().reverse().map(fmtN).join(' ; ')})`],{aide:['J’additionne les x, puis les y, puis les z.'],corr:[`~u~ + ~v~ = ${g}`],rep:`~u~ + ~v~ a pour coordonnées ${g}.`})); }
  const n=Math.hypot(...w); return item('v3-somme',[`Deux forces ~F₁~(${u.map(x=>fmtN(x*100)).join(' ; ')}) et ~F₂~(${v.map(x=>fmtN(x*100)).join(' ; ')}) en newtons.`],qN('**Calcule** l’intensité de la force résultante. **Arrondis** à l’unité.',n*100,{arr:0,unit:'N',aide:['Je calcule la somme des forces.','Puis la norme √(x² + y² + z²).'],corr:[`~F~(${w.map(x=>fmtN(x*100)).join(' ; ')})`,`‖~F~‖ ≈ ${fx(roundTo(n*100,0))}`],rep:`L’intensité est environ ${fx(roundTo(n*100,0))} N.`})); }
});
/* ===== Signaux sinusoïdaux (Tle) ===== */
Object.assign(GENS,{
'fr-periode':d=>{ const f=pick([50,100,125,200,250,400,500,1000]), A=pick([5,10,12,230,325]); const w=2*f; const T=1/f;
  if(d===1) return item('fr-periode',[`u(t) = ${A} sin(${w}πt).`],qN('**Calcule** la fréquence du signal.',f,{unit:'Hz',aide:['T = 2π ÷ ω, puis f = 1 ÷ T.',`Ou directement : f = ω ÷ (2π) = ${w}π ÷ 2π.`],corr:[`f = ${w}π ÷ 2π = ${f}`],rep:`La fréquence est ${f} Hz.`}));
  if(d===2) return item('fr-periode',[`u(t) = ${A} sin(${w}πt).`],qN('**Calcule** la période, en ms.',T*1000,{unit:'ms',aide:['T = 2π ÷ ω.','1 s = 1 000 ms.'],corr:[`T = 2π ÷ ${w}π = ${fx(T)} s`,`= ${fx(T*1000)} ms`],rep:`La période est ${fx(T*1000)} ms.`}));
  return item('fr-periode',[`Un signal a une fréquence de ${f} Hz.`],qN('**Calcule** sa pulsation ω. **Arrondis** à l’unité.',2*Math.PI*f,{arr:0,unit:'rad/s',aide:['ω = 2π × f.'],corr:[`2π × ${f} = ${2*f}π ≈ ${fx(roundTo(2*Math.PI*f,0))}`],rep:`ω ≈ ${fx(roundTo(2*Math.PI*f,0))} rad/s.`})); },
'fr-valeur':d=>{ const A=pick([5,10,12,20,230,325]), f=pick([50,100]), t=d===1?pick([0,0.25,0.5,0.75]).valueOf()/f:rnd(1,19)/1000; const ph=d===3?pick([Math.PI/6,Math.PI/4,Math.PI/3,-Math.PI/2]):0; const phs={[Math.PI/6]:' + π/6',[Math.PI/4]:' + π/4',[Math.PI/3]:' + π/3',[-Math.PI/2]:' − π/2',0:''}[ph];
  const v=A*Math.sin(2*Math.PI*f*t+ph); const vv=Math.abs(v)<1e-9?0:v;
  return item('fr-valeur',[`u(t) = ${A} sin(${2*f}πt${phs}), t en secondes.`],qN(`**Calcule** u(${fx(roundTo(t,4))}).${Number.isInteger(roundTo(vv*100,6))?'':' **Arrondis** au centième.'}`,vv,{arr:Number.isInteger(roundTo(vv*100,6))?null:2,aide:['Calculatrice en mode radian.',`Je calcule d’abord ${2*f}π × ${fx(roundTo(t,4))}${phs}.`],corr:[`u = ${A} × sin(${fx(roundTo(2*Math.PI*f*t+ph,4))}) ≈ ${fx(roundTo(vv,2))}`],rep:`u(${fx(roundTo(t,4))}) ≈ ${fx(roundTo(vv,2))}.`})); },
'fr-osc':d=>{ const nv=rnd(2,4), sv=pick([0.5,1,2,5]), nh=rnd(2,8), bt=pick([0.5,1,2,5,10]); const A=nv*sv, T=nh*bt, f=1000/T;
  if(d===1) return item('fr-osc',[`Sur l’oscilloscope, la courbe monte de ${nv} divisions. Sensibilité verticale : ${fx(sv)} V par division.`],qN('**Calcule** l’amplitude.',A,{unit:'V',aide:['Amplitude = divisions × sensibilité.'],corr:[`${nv} × ${fx(sv)} = ${fx(A)}`],rep:`L’amplitude est ${fx(A)} V.`}));
  return item('fr-osc',[`Sur l’oscilloscope, un motif occupe ${nh} divisions. Base de temps : ${fx(bt)} ms par division.`],qN(d===2?'**Calcule** la période, en ms.':`**Calcule** la fréquence.${Number.isInteger(roundTo(f*10,6))?'':' **Arrondis** à l’unité.'}`,d===2?T:f,{arr:d===3&&!Number.isInteger(roundTo(f*10,6))?0:null,unit:d===2?'ms':'Hz',aide:['Période = divisions × base de temps.',...(d===3?['f = 1 ÷ T, avec T en secondes.']:[])],corr:[`T = ${nh} × ${fx(bt)} = ${fx(T)} ms`,...(d===3?[`f = 1 ÷ ${fx(T/1000)} ≈ ${fx(roundTo(f,1))}`]:[])],rep:d===2?`La période est ${fx(T)} ms.`:`La fréquence est environ ${fx(roundTo(f,0))} Hz.`})); },
'fr-dephas':d=>{ const P=[['π/6',30,6],['π/4',45,4],['π/3',60,3],['π/2',90,2],['π',180,1]]; const p=pick(P), f=pick([50,100,200]);
  if(d===1) return item('fr-dephas',[`Le déphasage entre deux tensions est ${p[0]} rad.`],qN('**Convertis** ce déphasage en degrés.',p[1],{unit:'°',aide:['π rad = 180°.'],corr:[`${p[0]} = 180 ÷ ${p[2]} = ${p[1]}°`],rep:`Le déphasage est ${p[1]}°.`}));
  const dt=1/(2*f*p[2])*1000; return item('fr-dephas',[`Deux tensions de fréquence ${f} Hz sont déphasées de ${p[0]} rad.`],qN('**Calcule** le décalage dans le temps, en ms.',dt,{unit:'ms',aide:['ω = 2π × f.','Δt = déphasage ÷ ω.'],corr:[`ω = ${2*f}π`,`Δt = (${p[0]}) ÷ ${2*f}π = ${fx(roundTo(dt/1000,6))} s = ${fx(roundTo(dt,4))} ms`],rep:`Le décalage est ${fx(roundTo(dt,4))} ms.`})); }
});
